import math
import heapq

class Solution:
    def pickGifts(self, gifts: list[int], k: int) -> int:
        pq = [-x for x in gifts]
        heapq.heapify(pq)
        for _ in range(k):
            x = -heapq.heappop(pq)
            heapq.heappush(pq, -int(math.isqrt(x)))
        return -sum(pq)

class Solution {
public:
    long long pickGifts(std::vector<int>& gifts, int k) {
        std::priority_queue<int> pq(gifts.begin(), gifts.end());
        for (int i = 0; i < k; ++i) {
            int x = pq.top();
            pq.pop();
            pq.push((int)std::sqrt(x));
        }
        long long ans = 0;
        while (!pq.empty()) {
            ans += pq.top();
            pq.pop();
        }
        return ans;
    }
};

class Solution {
    public long pickGifts(int[] gifts, int k) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int x : gifts) pq.offer(x);
        for (int i = 0; i < k; i++) {
            int x = pq.poll();
            pq.offer((int)Math.sqrt(x));
        }
        long ans = 0;
        while (!pq.isEmpty()) ans += pq.poll();
        return ans;
    }
}

var pickGifts = function(gifts, k) {
    class MaxHeap {
        constructor(arr) {
            this.data = arr.slice();
            for (let i = (this.data.length >> 1) - 1; i >= 0; i--) this.down(i);
        }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[i] > this.data[p]) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.data[left] > this.data[best]) best = left;
                if (right < len && this.data[right] > this.data[best]) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const pq = new MaxHeap(gifts);
    for (let i = 0; i < k; i++) {
        const x = pq.pop();
        pq.push(Math.floor(Math.sqrt(x)));
    }
    let ans = 0;
    for (const val of pq.data) ans += val;
    return ans;
};
